}

struct Tokenizer {
    input: Vec<char>,
    pos: usize,
    state: State,
    /// Name of the element currently being entered in a raw text mode.
    last_start_tag: String,
}

impl Tokenizer {
    fn new(input: Vec<char>) -> Tokenizer {
        Tokenizer {
            input,
            pos: 0,
            state: State::Data,
            last_start_tag: String::new(),
        }
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<char> {
        self.input.get(self.pos + off).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn starts_with(&self, s: &str) -> bool {
        let mut i = 0;
        for ch in s.chars() {
            if self.peek_at(i) != Some(ch) {
                return false;
            }
            i += 1;
        }
        true
    }

    fn consume(&mut self, s: &str) {
        self.pos += s.chars().count();
    }

    fn emit_eof(&mut self, out: &mut Vec<Token>) {
        out.push(Token::Eof);
    }

    fn tokens(&mut self) -> Vec<Token> {
        let mut out: Vec<Token> = Vec::new();
        loop {
            if let Some(t) = self.step(&mut out) {
                out.push(t);
            }
            if let Some(Token::Eof) = out.last() {
                break;
            }
            if self.pos > self.input.len() + 8 {
                self.emit_eof(&mut out);
            }
        }
        out
    }

    fn step(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.state {
            State::Data => self.data_state(out),
            State::TagOpen => self.tag_open_state(out),
            State::EndTagOpen => self.end_tag_open_state(out),
            State::TagName => self.tag_name_state(out, false),
            State::BeforeAttributeName => self.before_attribute_name_state(out),
            State::AfterAttributeName => self.after_attribute_name_state(out),
            State::AttributeName => self.attribute_name_state(out),
            State::AttributeValueDouble => self.attribute_value_quoted_state(out, '"'),
            State::AttributeValueSingle => self.attribute_value_quoted_state(out, '\''),
            State::AttributeValueUnquoted => self.attribute_value_unquoted_state(out),
            State::AfterAttributeValueQuoted => self.after_attribute_value_quoted_state(out),
            State::SelfClosingStartTag => self.self_closing_start_tag_state(out),
            State::BogusComment => self.bogus_comment_state(out),
            State::MarkupDeclarationOpen => self.markup_declaration_open_state(out),
            State::CommentStart => self.comment_start_state(out),
            State::CommentStartDash => self.comment_start_dash_state(out),
            State::Comment => self.comment_state(out),
            State::CommentLessThanSign => self.comment_less_than_sign_state(out),
            State::CommentLessThanSignBang => self.comment_less_than_sign_bang_state(out),
            State::CommentLessThanSignBangDash => self.comment_less_than_sign_bang_dash_state(out),
            State::CommentLessThanSignBangDashDash => {
                self.comment_less_than_sign_bang_dash_dash_state(out)
            }
            State::CommentEndDash => self.comment_end_dash_state(out),
            State::CommentEnd => self.comment_end_state(out),
            State::CommentEndBang => self.comment_end_bang_state(out),
            State::DoctypeState => self.doctype_state(out),
            State::BeforeDoctypeName => self.before_doctype_name_state(out),
            State::DoctypeName => self.doctype_name_state(out),
            State::AfterDoctypeName => self.after_doctype_name_state(out),
            State::BogusDoctype => self.bogus_doctype_state(out),
            State::RawText => self.raw_text_state(out),
            State::RawTextLessThanSign => self.raw_text_less_than_sign_state(out),
            State::RawTextEndTagOpen => self.raw_text_end_tag_open_state(out),
            State::RawTextEndTagName => self.raw_text_end_tag_name_state(out),
            State::ScriptDataEscapeStart => self.script_data_escape_start_state(out),
            State::ScriptDataEscapeStartDash => self.script_data_escape_start_dash_state(out),
            State::ScriptDataEscaped => self.script_data_escaped_state(out),
            State::ScriptDataEscapedDash => self.script_data_escaped_dash_state(out),
            State::ScriptDataEscapedDashDash => self.script_data_escaped_dash_dash_state(out),
            State::ScriptDataEscapedLessThanSign => {
                self.script_data_escaped_less_than_sign_state(out)
            }
            State::ScriptDataEscapedEndTagOpen => self.raw_text_end_tag_open_state(out),
            State::ScriptDataEscapedEndTagName => self.raw_text_end_tag_name_state(out),
            State::RcData => self.rcdata_state(out),
            State::RcDataLessThanSign => self.rcdata_less_than_sign_state(out),
            State::RcDataEndTagOpen => self.rcdata_end_tag_open_state(out),
            State::RcDataEndTagName => self.rcdata_end_tag_name_state(out),
            State::PlainText => self.plaintext_state(out),
            State::CdataSection => self.cdata_section_state(out),
            State::CdataSectionBracket => self.cdata_section_bracket_state(out),
            State::CdataSectionEnd => self.cdata_section_end_state(out),
        }
    }

    fn flush_chars(&mut self, buf: &mut Vec<char>, out: &mut Vec<Token>) -> Option<Token> {
        if buf.is_empty() {
            return None;
        }
        let chars = std::mem::take(buf);
        Some(Token::Chars(chars))
    }

    fn data_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    out.push(Token::Eof);
                    return None;
                }
                Some('&') => {
                    self.consume_reference(&mut buf, false);
                }
                Some('<') => {
                    self.state = State::TagOpen;
                    break;
                }
                Some(c) => buf.push(c),
            }
        }
        self.flush_chars(&mut buf, out)
    }

    fn consume_reference(&mut self, buf: &mut Vec<char>, in_attr: bool) {
        let rest = &self.input[self.pos..];
        match rest.first() {
            None => {
                buf.push('&');
            }
            Some('#') => {
                // Numeric reference.
                let (value, len) = numeric_reference(&rest[1..]);
                if let Some(c) = value {
                    buf.push(c);
                    self.pos += 1 + len;
                } else {
                    buf.push('&');
                }
            }
            Some(c) if c.is_ascii_alphanumeric() => {
                if let Some((chars, len)) = entities::match_named(rest) {
                    let terminated = rest.get(len) == Some(&';');
                    if !terminated && in_attr {
                        if let Some(&n) = rest.get(len) {
                            if n == '=' || n.is_ascii_alphanumeric() {
                                buf.push('&');
                                return;
                            }
                        }
                    }
                    buf.extend(chars);
                    self.pos += len;
                    if terminated {
                        self.pos += 1;
                    }
                } else {
                    buf.push('&');
                }
            }
            Some(_) => {
                buf.push('&');
            }
        }
    }

    fn tag_open_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.peek() {
            None => {
                out.push(Token::Chars(vec!['<']));
                out.push(Token::Eof);
                None
            }
            Some('!') => {
                self.state = State::MarkupDeclarationOpen;
                self.pos += 1;
                None
            }
            Some('/') => {
                self.state = State::EndTagOpen;
                self.pos += 1;
                None
            }
            Some(c) if c.is_ascii_alphabetic() => {
                self.state = State::TagName;
                Some(Token::StartTag {
                    name: String::new(),
                    attrs: Vec::new(),
                    self_closing: false,
                })
            }
            Some('?') => {
                self.state = State::BogusComment;
                self.pos += 1;
                None
            }
            Some(_) => {
                self.state = State::Data;
                Some(Token::Chars(vec!['<']))
            }
        }
    }

    fn end_tag_open_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.peek() {
            None => {
                out.push(Token::Chars(vec!['<', '/']));
                out.push(Token::Eof);
                None
            }
            Some('>') => {
                self.state = State::Data;
                self.pos += 1;
                None
            }
            Some(c) if c.is_ascii_alphabetic() => {
                self.state = State::TagName;
                Some(Token::EndTag { name: String::new() })
            }
            Some(_) => {
                self.state = State::BogusComment;
                self.pos += 1;
                None
            }
        }
    }

    fn tag_name_state(&mut self, out: &mut Vec<Token>, is_end: bool) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    // EOF in tag: emit what we have.
                    self.state = State::Data;
                    let name: String = buf.iter().collect();
                    if is_end {
                        return Some(Token::EndTag { name });
                    }
                    return Some(Token::StartTag {
                        name,
                        attrs: Vec::new(),
                        self_closing: false,
                    });
                }
                Some(c) if c.is_ascii_whitespace() => {
                    self.state = State::BeforeAttributeName;
                    break;
                }
                Some('/') => {
                    self.state = State::SelfClosingStartTag;
                    break;
                }
                Some('>') => {
                    self.state = State::Data;
                    break;
                }
                Some(c) => buf.push(c.to_ascii_lowercase()),
            }
        }
        let name: String = buf.iter().collect();
        if is_end {
            return Some(Token::EndTag { name });
        }
        return Some(Token::StartTag {
            name,
            attrs: Vec::new(),
            self_closing: false,
        });
    }

    fn before_attribute_name_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    out.push(Token::Eof);
                    return None;
                }
                Some(c) if c.is_ascii_whitespace() => {}
                Some('/') => {
                    self.state = State::SelfClosingStartTag;
                    return None;
                }
                Some('>') => {
                    self.state = State::Data;
                    return None;
                }
                Some('=') => {
                    // Unexpected equals sign: it becomes part of the name.
                    self.state = State::AttributeName;
                    return Some(Token::StartTag {
                        name: String::new(),
                        attrs: vec![("=".to_string(), String::new())],
                        self_closing: false,
                    });
                }
                Some(_) => {
                    self.state = State::AttributeName;
                    return None;
                }
            }
        }
    }

    fn after_attribute_name_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                out.push(Token::Eof);
                None
            }
            Some(c) if c.is_ascii_whitespace() => {
                self.state = State::BeforeAttributeName;
                None
            }
            Some('/') => {
                self.state = State::SelfClosingStartTag;
                None
            }
            Some('=') => {
                self.state = State::AttributeValueDouble;
                None
            }
            Some('>') => {
                self.state = State::Data;
                None
            }
            Some(_) => {
                self.state = State::AttributeName;
                None
            }
        }
    }

    fn attribute_name_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    out.push(Token::Eof);
                    return None;
                }
                Some(c) if c.is_ascii_whitespace() => {
                    self.state = State::AfterAttributeName;
                    return None;
                }
                Some('/') => {
                    self.state = State::AfterAttributeName;
                    self.pos -= 1;
                    return None;
                }
                Some('=') => {
                    self.state = State::AttributeValueDouble;
                    return None;
                }
                Some('>') => {
                    self.state = State::Data;
                    self.pos -= 1;
                    return None;
                }
                Some(_) => {}
            }
        }
    }

    fn attribute_value_quoted_state(&mut self, out: &mut Vec<Token>, quote: char) -> Option<Token> {
        // We are just after the `=`; skip optional whitespace and then read.
        while matches!(self.peek(), Some(c) if c.is_ascii_whitespace()) {
            self.pos += 1;
        }
        match self.peek() {
            Some(c) if c == quote => {
                self.pos += 1;
            }
            Some('>') => {
                self.state = State::Data;
                return None;
            }
            Some(_) => {
                // Wrong quote: treat as unquoted-ish, but per spec we read until the
                // closing quote.
            }
            None => {
                self.state = State::Data;
                out.push(Token::Eof);
                return None;
            }
        }
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    out.push(Token::Eof);
                    return None;
                }
                Some(c) if c == quote => {
                    self.state = State::AfterAttributeValueQuoted;
                    break;
                }
                Some('&') => self.consume_reference(&mut buf, true),
                Some(c) => buf.push(c),
            }
        }
        if buf.is_empty() {
            return None;
        }
        let value: String = buf.iter().collect();
        Some(Token::StartTag {
            name: String::new(),
            attrs: vec!((String::new(), value)),
            self_closing: false,
        })
    }

    fn attribute_value_unquoted_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    out.push(Token::Eof);
                    return None;
                }
                Some(c) if c.is_ascii_whitespace() => {
                    self.state = State::BeforeAttributeName;
                    break;
                }
                Some('&') => self.consume_reference(&mut buf, true),
                Some('>') => {
                    self.state = State::Data;
                    break;
                }
                Some(c) => buf.push(c),
            }
        }
        if buf.is_empty() {
            return None;
        }
        let value: String = buf.iter().collect();
        Some(Token::StartTag {
            name: String::new(),
            attrs: vec!((String::new(), value)),
            self_closing: false,
        })
    }

    fn after_attribute_value_quoted_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                None
            }
            Some(c) if c.is_ascii_whitespace() => {
                self.state = State::BeforeAttributeName;
                None
            }
            Some('/') => {
                self.state = State::SelfClosingStartTag;
                None
            }
            Some('>') => {
                self.state = State::Data;
                None
            }
            Some(_) => {
                self.state = State::BeforeAttributeName;
                None
            }
        }
    }

    fn self_closing_start_tag_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                out.push(Token::Eof);
                None
            }
            Some('>') => {
                self.state = State::Data;
                out.push(Token::Eof);
                None
            }
            Some(_) => {
                self.state = State::BeforeAttributeName;
                None
            }
        }
    }

    fn bogus_comment_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    out.push(Token::Eof);
                    break;
                }
                Some('>') => {
                    self.state = State::Data;
                    break;
                }
                Some(c) => buf.push(c),
            }
        }
        let data: String = buf.iter().collect();
        Some(Token::Comment(data))
    }

    fn markup_declaration_open_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        if self.starts_with("--") {
            self.consume("--");
            self.state = State::CommentStart;
            None
        } else if self.starts_with("doctype") || self.starts_with("DOCTYPE") {
            self.consume("doctype");
            self.state = State::BeforeDoctypeName;
            None
        } else if self.starts_with("[CDATA[") {
            self.consume("[CDATA[");
            self.state = State::CdataSection;
            None
        } else {
            self.state = State::BogusComment;
            None
        }
    }

    fn comment_start_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                None
            }
            Some('-') => {
                self.state = State::CommentStartDash;
                None
            }
            Some('>') => {
                self.state = State::Data;
                None
            }
            Some(_) => {
                self.state = State::Comment;
                None
            }
        }
    }

    fn comment_start_dash_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                None
            }
            Some('-') => {
                self.state = State::CommentEnd;
                None
            }
            Some('>') => {
                self.state = State::Data;
                None
            }
            Some(_) => {
                self.state = State::Comment;
                None
            }
        }
    }

    fn comment_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    return None;
                }
                Some('<') => {
                    self.state = State::CommentLessThanSign;
                    return None;
                }
                Some('-') => {
                    self.state = State::CommentEndDash;
                    return None;
                }
                Some(_) => {}
            }
        }
    }

    fn comment_less_than_sign_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            Some('!') => {
                self.state = State::CommentLessThanSignBang;
                None
            }
            Some('<') => {
                self.state = State::CommentLessThanSign;
                None
            }
            Some(_) => {
                self.state = State::Comment;
                None
            }
            None => {
                self.state = State::Data;
                None
            }
        }
    }

    fn comment_less_than_sign_bang_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            Some('-') => {
                self.state = State::CommentLessThanSignBangDash;
                None
            }
            Some(_) => {
                self.state = State::Comment;
                None
            }
            None => {
                self.state = State::Data;
                None
            }
        }
    }

    fn comment_less_than_sign_bang_dash_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            Some('-') => {
                self.state = State::CommentLessThanSignBangDashDash;
                None
            }
            Some(_) => {
                self.state = State::CommentEndDash;
                None
            }
            None => {
                self.state = State::Data;
                None
            }
        }
    }

    fn comment_less_than_sign_bang_dash_dash_state(
        &mut self,
        _out: &mut Vec<Token>,
    ) -> Option<Token> {
        match self.next() {
            Some('>') => {
                self.state = State::Data;
                None
            }
            None => {
                self.state = State::Data;
                None
            }
            Some(_) => {
                self.state = State::CommentEnd;
                None
            }
        }
    }

    fn comment_end_dash_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                None
            }
            Some('-') => {
                self.state = State::CommentEnd;
                None
            }
            Some(_) => {
                self.state = State::Comment;
                None
            }
        }
    }

    fn comment_end_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                None
            }
            Some('>') => {
                self.state = State::Data;
                None
            }
            Some('!') => {
                self.state = State::CommentEndBang;
                None
            }
            Some('-') => {
                self.state = State::CommentEnd;
                None
            }
            Some(_) => {
                self.state = State::Comment;
                None
            }
        }
    }

    fn comment_end_bang_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                None
            }
            Some('-') => {
                self.state = State::CommentEndDash;
                None
            }
            Some('>') => {
                self.state = State::Data;
                None
            }
            Some(_) => {
                self.state = State::Comment;
                None
            }
        }
    }

    fn doctype_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    return None;
                }
                Some('>') => {
                    self.state = State::Data;
                    Some(Token::Doctype)
                }
                Some(_) => {}
            }
        }
    }

    fn before_doctype_name_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                Some(Token::Doctype)
            }
            Some('>') => {
                self.state = State::Data;
                Some(Token::Doctype)
            }
            Some(_) => {
                self.state = State::DoctypeName;
                None
            }
        }
    }

    fn doctype_name_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    return Some(Token::Doctype);
                }
                Some(c) if c.is_ascii_whitespace() => {
                    self.state = State::AfterDoctypeName;
                    return None;
                }
                Some('>') => {
                    self.state = State::Data;
                    return Some(Token::Doctype);
                }
                Some(_) => {}
            }
        }
    }

    fn after_doctype_name_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    return Some(Token::Doctype);
                }
                Some('>') => {
                    self.state = State::Data;
                    return Some(Token::Doctype);
                }
                Some(_) => {}
            }
        }
    }

    fn bogus_doctype_state(&mut self, _out: &mut Vec<Token>) -> Option<Token> {
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    return Some(Token::Doctype);
                }
                Some('>') => {
                    self.state = State::Data;
                    return Some(Token::Doctype);
                }
                Some(_) => {}
            }
        }
    }

    fn raw_text_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    break;
                }
                Some('<') => {
                    self.state = State::RawTextLessThanSign;
                    break;
                }
                Some(c) => buf.push(c),
            }
        }
        if buf.is_empty() {
            return None;
        }
        let chars = buf;
        Some(Token::Chars(chars))
    }

    fn raw_text_less_than_sign_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['<']))
            }
            Some('/') => {
                self.state = State::RawTextEndTagOpen;
                None
            }
            Some(_) => {
                self.state = State::RawText;
                Some(Token::Chars(vec!['<']))
            }
        }
    }

    fn raw_text_end_tag_open_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.peek() {
            Some(c) if c.is_ascii_alphabetic() => {
                self.pos += 1;
                self.state = State::RawTextEndTagName;
                None
            }
            Some(_) => {
                self.state = State::RawText;
                Some(Token::Chars(vec!['<', '/']))
            }
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['<', '/']))
            }
        }
    }

    fn raw_text_end_tag_name_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = vec!();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    break;
                }
                Some(c) if c.is_ascii_whitespace() => {
                    self.state = State::RawText;
                    break;
                }
                Some('/') => {
                    self.state = State::RawText;
                    break;
                }
                Some('>') => {
                    self.state = State::Data;
                    break;
                }
                Some(c) => buf.push(c.to_ascii_lowercase()),
            }
        }
        let name: String = buf.iter().collect();
        if name == self.last_start_tag {
            if name.is_empty() {
                return None;
            }
            return Some(Token::EndTag { name });
        }
        // Not the appropriate end tag: emit the consumed characters as text.
        let mut chars = vec!['<', '/'];
        chars.extend(buf.iter().copied());
        Some(Token::Chars(chars))
    }

    fn script_data_escape_start_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['<']))
            }
            Some('-') => {
                self.state = State::ScriptDataEscapeStartDash;
                None
            }
            Some(c) => {
                self.state = State::ScriptDataEscaped;
                Some(Token::Chars(vec!['<', c]))
            }
        }
    }

    fn script_data_escape_start_dash_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['<', '-']))
            }
            Some('-') => {
                self.state = State::ScriptDataEscapedDashDash;
                None
            }
            Some(_) => {
                self.state = State::ScriptDataEscaped;
                Some(Token::Chars(vec!['<', '-']))
            }
        }
    }

    fn script_data_escaped_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    break;
                }
                Some('-') => {
                    self.state = State::ScriptDataEscapedDash;
                    break;
                }
                Some('<') => {
                    self.state = State::ScriptDataEscapedLessThanSign;
                    break;
                }
                Some(c) => buf.push(c),
            }
        }
        if buf.is_empty() {
            return None;
        }
        Some(Token::Chars(buf))
    }

    fn script_data_escaped_dash_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['-']))
            }
            Some('-') => {
                self.state = State::ScriptDataEscapedDashDash;
                None
            }
            Some('<') => {
                self.state = State::ScriptDataEscapedLessThanSign;
                Some(Token::Chars(vec!['-']))
            }
            Some(c) => {
                self.state = State::ScriptDataEscaped;
                Some(Token::Chars(vec!['-', c]))
            }
        }
    }

    fn script_data_escaped_dash_dash_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['-', '-']))
            }
            Some('-') => {
                self.state = State::ScriptDataEscapedDashDash;
                Some(Token::Chars(vec!['-']))
            }
            Some('<') => {
                self.state = State::ScriptDataEscapedLessThanSign;
                Some(Token::Chars(vec!['-']))
            }
            Some('>') => {
                self.state = State::ScriptDataEscaped;
                Some(Token::Chars(vec!['-', '-', '>']))
            }
            Some(c) => {
                self.state = State::ScriptDataEscaped;
                Some(Token::Chars(vec!['-', '-', c]))
            }
        }
    }

    fn script_data_escaped_less_than_sign_state(
        &mut self,
        out: &mut Vec<Token>,
    ) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['<']))
            }
            Some('/') => {
                self.state = State::RawTextEndTagOpen;
                None
            }
            Some(c) => {
                self.state = State::ScriptDataEscaped;
                Some(Token::Chars(vec!['<', c]))
            }
        }
    }

    fn rcdata_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    break;
                }
                Some('&') => self.consume_reference(&mut buf, false),
                Some('<') => {
                    self.state = State::RcDataLessThanSign;
                    break;
                }
                Some(c) => buf.push(c),
            }
        }
        if buf.is_empty() {
            return None;
        }
        Some(Token::Chars(buf))
    }

    fn rcdata_less_than_sign_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['<']))
            }
            Some('/') => {
                self.state = State::RcDataEndTagOpen;
                None
            }
            Some(_) => {
                self.state = State::RcData;
                Some(Token::Chars(vec!['<']))
            }
        }
    }

    fn rcdata_end_tag_open_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.peek() {
            Some(c) if c.is_ascii_alphabetic() => {
                self.pos += 1;
                self.state = State::RcDataEndTagName;
                None
            }
            Some(_) => {
                self.state = State::RcData;
                Some(Token::Chars(vec!['<', '/']))
            }
            None => {
                self.state = State::Data;
                Some(Token::Chars(vec!['<', '/']))
            }
        }
    }

    fn rcdata_end_tag_name_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    break;
                }
                Some(c) if c.is_ascii_whitespace() => {
                    self.state = State::Data;
                    break;
                }
                Some('/') => {
                    self.state = State::Data;
                    break;
                }
                Some('>') => {
                    self.state = State::Data;
                    break;
                }
                Some(c) => buf.push(c.to_ascii_lowercase()),
            }
        }
        let name: String = buf.iter().collect();
        if name == self.last_start_tag && !name.is_empty() {
            return Some(Token::EndTag { name });
        }
        let mut chars = vec!['<', '/'];
        chars.extend(buf.iter().copied());
        Some(Token::Chars(chars))
    }

    fn plaintext_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let buf: Vec<char> = self.input[self.pos..].to_vec();
        self.pos = self.input.len();
        self.state = State::Data;
        if buf.is_empty() {
            out.push(Token::Eof);
            return None;
        }
        Some(Token::Chars(buf))
    }

    fn cdata_section_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        let mut buf: Vec<char> = Vec::new();
        loop {
            match self.next() {
                None => {
                    self.state = State::Data;
                    break;
                }
                Some(']') => {
                    self.state = State::CdataSectionBracket;
                    break;
                }
                Some(c) => buf.push(c),
            }
        }
        if buf.is_empty() {
            return None;
        }
        Some(Token::Comment(String::from_iter(buf)))
    }

    fn cdata_section_bracket_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            Some(']') => {
                self.state = State::CdataSectionEnd;
                None
            }
            Some(_) => {
                self.state = State::CdataSection;
                Some(Token::Comment("]".to_string()))
            }
            None => {
                self.state = State::Data;
                Some(Token::Comment("]".to_string()))
            }
        }
    }

    fn cdata_section_end_state(&mut self, out: &mut Vec<Token>) -> Option<Token> {
        match self.next() {
            Some('>') => {
                self.state = State::Data;
                None
            }
            Some(']') => {
                self.state = State::CdataSectionEnd;
                Some(Token::Comment("]".to_string()))
            }
            Some(_) => {
                self.state = State::CdataSection;
                Some(Token::Comment("]]".to_string()))
            }
            None => {
                self.state = State::Data;
                Some(Token::Comment("]]".to_string()))
            }
        }
    }
}

fn numeric_reference(s: &[char]) -> (Option<char>, usize) {
    if s.is_empty() {
        return (None, 0);
    }
    let mut hex = false;
    let mut i = 0;
    if s[0] == 'x' || s[0] == 'X' {
        hex = true;
        i = 1;
    }
    if i >= s.len() || !s[i].is_ascii_digit() {
        return (None, 0);
    }
    let mut value: u32 = 0;
    let mut overflow = false;
    while i < s.len() && s[i].is_ascii_digit() {
        let d = s[i].to_digit(16).unwrap();
        value = match value.checked_mul(16).and_then(|v| v.checked_add(d)) {
            Some(v) => v,
            None => {
                overflow = true;
                value
            }
        };
        i += 1;
    }
    if overflow {
        return (Some('\u{FFFD}'), i);
    }
    if value == 0 {
        return (Some('\u{FFFD}'), i);
    }
    let c = match char::from_u32(value) {
        None => '\u{FFFD}',
        Some(c) => {
            // Non-characters and control characters are also replaced.
            if value >= 0xD800 && value <= 0xDFFF {
                '\u{FFFD}'
            } else {
                c
            }
        }
    };
    (Some(c), i)
}
