// HTML5 tokenizer and tree construction. Reproduces the observable behaviour of
// the reference parser: error recovery, implied end tags, foster parenting,
// foreign content handling and the adoption agency algorithm.

use crate::entities;

pub const NS_HTML: &str = "http://www.w3.org/1999/xhtml";
pub const NS_MATHML: &str = "http://www.w3.org/1998/Math/MathML";
pub const NS_SVG: &str = "http://www.w3.org/2000/svg";
pub const NS_XLINK: &str = "http://www.w3.org/1999/xlink";
pub const NS_XML: &str = "http://www.w3.org/XML/1998/namespace";
pub const NS_XMLNS: &str = "http://www.w3.org/2000/xmlns/";

#[derive(Clone, Debug, PartialEq)]
pub enum NodeData {
    Document,
    Doctype(String),
    Text(String),
    Comment(String),
    Element(ElementData),
}

#[derive(Clone, Debug, PartialEq)]
pub struct ElementData {
    pub name: QualName,
    pub attrs: Vec<(QualName, String)>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct QualName {
    pub ns: Option<String>,
    pub local: String,
}

impl PartialOrd for QualName {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for QualName {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        // A missing namespace sorts before any namespace.
        self.ns.cmp(&other.ns).then(self.local.cmp(&other.local))
    }
}

impl QualName {
    fn html(local: &str) -> QualName {
        QualName {
            ns: None,
            local: local.to_string(),
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Node {
    pub data: NodeData,
    pub parent: Option<usize>,
    pub children: Vec<usize>,
}

pub struct Tree {
    pub nodes: Vec<Node>,
    pub document: usize,
}

impl Tree {
    pub fn data(&self, i: usize) -> &NodeData {
        &self.nodes[i].data
    }

    pub fn element(&self, i: usize) -> Option<&ElementData> {
        match &self.nodes[i].data {
            NodeData::Element(e) => Some(e),
            _ => None,
        }
    }

    pub fn children(&self, i: usize) -> &[usize] {
        &self.nodes[i].children
    }

    pub fn parent(&self, i: usize) -> Option<usize> {
        self.nodes[i].parent
    }

    fn new_node(&mut self, data: NodeData) -> usize {
        self.nodes.push(Node {
            data,
            parent: None,
            children: Vec::new(),
        });
        self.nodes.len() - 1
    }

    fn append(&mut self, parent: usize, child: usize) {
        self.nodes[child].parent = Some(parent);
        self.nodes[parent].children.push(child);
    }

    /// Insert `child` directly after `sibling` in the parent's child list.
    fn insert_after(&mut self, parent: usize, sibling: usize, child: usize) {
        self.nodes[child].parent = Some(parent);
        let pos = self.nodes[parent]
            .children
            .iter()
            .position(|&c| c == sibling)
            .map(|p| p + 1)
            .unwrap_or(self.nodes[parent].children.len());
        self.nodes[parent].children.insert(pos, child);
    }

    fn detach(&mut self, child: usize) {
        if let Some(p) = self.nodes[child].parent {
            self.nodes[p].children.retain(|&c| c != child);
            self.nodes[child].parent = None;
        }
    }

    /// Remove the last text node child of `parent` and return its data.
    fn pop_text(&mut self, parent: usize) -> Option<String> {
        let child = *self.nodes[parent].children.last()?;
        match &self.nodes[child].data {
            NodeData::Text(_) => {
                let data = match &self.nodes[child].data {
                    NodeData::Text(t) => t.clone(),
                    _ => unreachable!(),
                };
                self.detach(child);
                Some(data)
            }
            _ => None,
        }
    }

    /// Text content of a node's subtree (only element children).
    pub fn text_contents(&self, i: usize) -> String {
        let mut out = String::new();
        self.collect_text(i, &mut out);
        out
    }

    fn collect_text(&self, i: usize, out: &mut String) {
        match &self.nodes[i].data {
            NodeData::Text(t) => out.push_str(t),
            NodeData::Document => {
                for &c in &self.nodes[i].children {
                    self.collect_text(c, out);
                }
            }
            NodeData::Element(_) => {
                for &c in &self.nodes[i].children {
                    self.collect_text(c, out);
                }
            }
            _ => {}
        }
    }

    pub fn descendants(&self, i: usize) -> Vec<usize> {
        let mut out = Vec::new();
        self.collect_desc(i, &mut out);
        out
    }

    fn collect_desc(&self, i: usize, out: &mut Vec<usize>) {
        for &c in &self.nodes[i].children {
            out.push(c);
            self.collect_desc(c, out);
        }
    }

    /// Every element in the subtree, in document order (including `i`).
    pub fn elements(&self, i: usize) -> Vec<usize> {
        let mut out = Vec::new();
        self.collect_elems(i, &mut out);
        out
    }

    fn collect_elems(&self, i: usize, out: &mut Vec<usize>) {
        if self.element(i).is_some() {
            out.push(i);
        }
        for &c in &self.nodes[i].children {
            self.collect_elems(c, out);
        }
    }

    pub fn is_element(&self, i: usize) -> bool {
        matches!(self.nodes[i].data, NodeData::Element(_))
    }
}

