// HTML5 tokenizer + tree construction.
//
// This reproduces the observable behaviour of the reference parser:
// error recovery, implied end tags, foster parenting, foreign content
// handling, the list of active formatting elements and the adoption
// agency algorithm.

use crate::entities;

pub const NS_HTML: &str = "http://www.w3.org/1999/xhtml";
pub const NS_MATHML: &str = "http://www.w3.org/1998/Math/MathML";
pub const NS_SVG: &str = "http://www.w3.org/2000/svg";
pub const NS_XLINK: &str = "http://www.w3.org/1999/xlink";
pub const NS_XML: &str = "http://www.w3.org/XML/1998/namespace";
pub const NS_XMLNS: &str = "http://www.w3.org/2000/xmlns/";

#[derive(Clone, Debug, PartialEq)]
pub enum NodeData {
    Document,
    Doctype(String),
    Text(String),
    Comment(String),
    Element(ElementData),
}

#[derive(Clone, Debug, PartialEq)]
pub struct ElementData {
    pub name: QualName,
    pub attrs: Vec<(QualName, String)>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct QualName {
    pub ns: Option<String>,
    pub local: String,
}

impl PartialOrd for QualName {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for QualName {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.ns.cmp(&other.ns).then(self.local.cmp(&other.local))
    }
}

impl QualName {
    fn html(local: &str) -> QualName {
        QualName {
            ns: None,
            local: local.to_string(),
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Node {
    pub data: NodeData,
    pub parent: Option<usize>,
    pub children: Vec<usize>,
}

pub struct Tree {
    pub nodes: Vec<Node>,
    pub document: usize,
}

impl Tree {
    pub fn data(&self, i: usize) -> &NodeData {
        &self.nodes[i].data
    }

    pub fn element(&self, i: usize) -> Option<&ElementData> {
        match &self.nodes[i].data {
            NodeData::Element(e) => Some(e),
            _ => None,
        }
    }

    pub fn element_mut(&mut self, i: usize) -> Option<&mut ElementData> {
        match &mut self.nodes[i].data {
            NodeData::Element(e) => Some(e),
            _ => None,
        }
    }

    pub fn children(&self, i: usize) -> &[usize] {
        &self.nodes[i].children
    }

    pub fn parent(&self, i: usize) -> Option<usize> {
        self.nodes[i].parent
    }

    pub fn name(&self, i: usize) -> Option<&str> {
        self.element(i).map(|e| e.name.local.as_str())
    }

    pub fn attr(&self, i: usize, name: &str) -> Option<&str> {
        let e = self.element(i)?;
        self.nodes[i]
            .data
            .as_element()
            .and_then(|_| e.attrs.iter().find(|(k, _)| k.local == name))
            .map(|(_, v)| v.as_str())
    }

    /// Text content of a node's subtree.
    pub fn text_contents(&self, i: usize) -> String {
        let mut out = String::new();
        self.collect_text(i, &mut out);
        out
    }

    fn collect_text(&self, i: usize, out: &mut String) {
        match &self.nodes[i].data {
            NodeData::Text(t) => out.push_str(t),
            NodeData::Document | NodeData::Element(_) => {
                for &c in &self.nodes[i].children {
                    self.collect_text(c, out);
                }
            }
            _ => {}
        }
    }

    /// All nodes in the subtree, in document order (excluding `i` itself).
    pub fn descendants(&self, i: usize) -> Vec<usize> {
        let mut out = Vec::new();
        self.collect_desc(i, &mut out);
        out
    }

    fn collect_desc(&self, i: usize, out: &mut Vec<usize>) {
        for &c in &self.nodes[i].children {
            out.push(c);
            self.collect_desc(c, out);
        }
    }

    pub fn is_element(&self, i: usize) -> bool {
        matches!(self.nodes[i].data, NodeData::Element(_))
    }
}

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq)]
pub enum Token {
    Doctype,
    StartTag {
        name: String,
        attrs: Vec<(String, String)>,
        self_closing: bool,
    },
    EndTag {
        name: String,
    },
    Comment(String),
    Chars(Vec<char>),
    Eof,
}

#[derive(Clone, Copy, PartialEq)]
enum State {
    Data,
    TagOpen,
    EndTagOpen,
    TagName,
    BeforeAttributeName,
    AfterAttributeName,
    AttributeName,
    BeforeAttributeValue,
    AttributeValueDouble,
    AttributeValueSingle,
    AttributeValueUnquoted,
    AfterAttributeValueQuoted,
    SelfClosingStartTag,
    BogusComment,
    MarkupDeclarationOpen,
    CommentStart,
    CommentStartDash,
    Comment,
    CommentLessThanSign,
    CommentLessThanSignBang,
    CommentLessThanSignBangDash,
    CommentLessThanSignBangDashDash,
    CommentEndDash,
    CommentEnd,
    CommentEndBang,
    BeforeDoctypeName,
    DoctypeName,
    AfterDoctypeName,
    RawText,
    RawTextLessThanSign,
    RawTextEndTagOpen,
    RawTextEndTagName,
    ScriptDataEscapeStart,
    ScriptDataEscapeStartDash,
    ScriptDataEscaped,
    ScriptDataEscapedDash,
    ScriptDataEscapedDashDash,
    ScriptDataEscapedLessThanSign,
    RcData,
    RcDataLessThanSign,
    RcDataEndTagOpen,
    RcDataEndTagName,
    PlainText,
    CdataSection,
    CdataSectionBracket,
    CdataSectionEnd,
}

struct Tokenizer {
    input: Vec<char>,
    pos: usize,
    state: State,
    tag_name: String,
    tag_attrs: Vec<(String, String)>,
    tag_self_closing: bool,
    tag_is_end: bool,
    text: String,
    comment: String,
    /// Tag name whose matching end tag terminates a raw text block.
    last_start_tag: String,
}

fn is_ws(c: char) -> bool {
    c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\u{c}'
}

impl Tokenizer {
    fn new(input: Vec<char>) -> Tokenizer {
        Tokenizer {
            input,
            pos: 0,
            state: State::Data,
            tag_name: String::new(),
            tag_attrs: Vec::new(),
            tag_self_closing: false,
            tag_is_end: false,
            text: String::new(),
            comment: String::new(),
            last_start_tag: String::new(),
        }
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn advance(&mut self) {
        self.pos += 1;
    }

    fn starts_with(&self, s: &str) -> bool {
        let mut i = 0;
        for ch in s.chars() {
            if self.input.get(self.pos + i) != Some(&ch) {
                return false;
            }
            i += 1;
        }
        true
    }

    fn emit_tag(&mut self) -> Token {
        let name = std::mem::take(&mut self.tag_name);
        let attrs = std::mem::take(&mut self.tag_attrs);
        let self_closing = self.tag_self_closing;
        self.tag_self_closing = false;
        let is_end = self.tag_is_end;
        self.tag_is_end = false;
        self.state = State::Data;
        if is_end {
            Token::EndTag { name }
        } else {
            Token::StartTag {
                name,
                attrs,
                self_closing,
            }
        }
    }

    /// Returns None while more tokens remain to be produced.
    fn step(&mut self) -> Option<Token> {
        match self.state {
            State::Data => self.data_state(),
            State::TagOpen => self.tag_open_state(),
            State::EndTagOpen => self.end_tag_open_state(),
            State::TagName => self.tag_name_state(),
            State::BeforeAttributeName => self.before_attribute_name_state(),
            State::AfterAttributeName => self.after_attribute_name_state(),
            State::AttributeName => self.attribute_name_state(),
            State::BeforeAttributeValue => self.before_attribute_value_state(),
            State::AttributeValueDouble => self.attribute_value_quoted_state('"'),
            State::AttributeValueSingle => self.attribute_value_quoted_state('\''),
            State::AttributeValueUnquoted => self.attribute_value_unquoted_state(),
            State::AfterAttributeValueQuoted => self.after_attribute_value_quoted_state(),
            State::SelfClosingStartTag => self.self_closing_start_tag_state(),
            State::BogusComment => self.bogus_comment_state(),
            State::MarkupDeclarationOpen => self.markup_declaration_open_state(),
            State::CommentStart => self.comment_start_state(),
            State::CommentStartDash => self.comment_start_dash_state(),
            State::Comment => self.comment_state(),
            State::CommentLessThanSign => self.comment_less_than_sign_state(),
            State::CommentLessThanSignBang => self.comment_less_than_sign_bang_state(),
            State::CommentLessThanSignBangDash => self.comment_less_than_sign_bang_dash_state(),
            State::CommentLessThanSignBangDashDash => {
                self.comment_less_than_sign_bang_dash_dash_state()
            }
            State::CommentEndDash => self.comment_end_dash_state(),
            State::CommentEnd => self.comment_end_state(),
            State::CommentEndBang => self.comment_end_bang_state(),
            State::BeforeDoctypeName => self.before_doctype_name_state(),
            State::DoctypeName => self.doctype_name_state(),
            State::AfterDoctypeName => self.after_doctype_name_state(),
            State::RawText => self.raw_text_state(),
            State::RawTextLessThanSign => self.raw_text_less_than_sign_state(),
            State::RawTextEndTagOpen => self.raw_text_end_tag_open_state(),
            State::RawTextEndTagName => self.raw_text_end_tag_name_state(),
            State::ScriptDataEscapeStart => self.script_data_escape_start_state(),
            State::ScriptDataEscapeStartDash => self.script_data_escape_start_dash_state(),
            State::ScriptDataEscaped => self.script_data_escaped_state(),
            State::ScriptDataEscapedDash => self.script_data_escaped_dash_state(),
            State::ScriptDataEscapedDashDash => self.script_data_escaped_dash_dash_state(),
            State::ScriptDataEscapedLessThanSign => self.script_data_escaped_less_than_sign_state(),
            State::RcData => self.rcdata_state(),
            State::RcDataLessThanSign => self.rcdata_less_than_sign_state(),
            State::RcDataEndTagOpen => self.rcdata_end_tag_open_state(),
            State::RcDataEndTagName => self.rcdata_end_tag_name_state(),
            State::PlainText => self.plaintext_state(),
            State::CdataSection => self.cdata_section_state(),
            State::CdataSectionBracket => self.cdata_section_bracket_state(),
            State::CdataSectionEnd => self.cdata_section_end_state(),
        }
    }

    fn data_state(&mut self) -> Option<Token> {
        loop {
            match self.peek() {
                None => {
                    self.advance();
                    if self.text.is_empty() {
                        return Some(Token::Eof);
                    }
                    let text = std::mem::take(&mut self.text);
                    return Some(Token::Chars(text.chars().collect()));
                }
                Some('&') => {
                    self.advance();
                    self.consume_reference(false);
                }
                Some('<') => {
                    self.advance();
                    self.state = State::TagOpen;
                    if self.text.is_empty() {
                        return None;
                    }
                    let text = std::mem::take(&mut self.text);
                    return Some(Token::Chars(text.chars().collect()));
                }
                Some(c) => {
                    self.advance();
                    if c == '\0' {
                        self.text.push('\u{FFFD}');
                    } else {
                        self.text.push(c);
                    }
                }
            }
        }
    }

    /// Consume a character reference at the current position.
    fn consume_reference(&mut self, in_attr: bool) {
        let rest = &self.input[self.pos..];
        match rest.first() {
            None => self.text.push('&'),
            Some('#') => {
                let (value, len) = numeric_reference(&rest[1..]);
                if let Some(c) = value {
                    self.text.push(c);
                    self.pos += 1 + len;
                } else {
                    self.text.push('&');
                }
            }
            Some(c) if c.is_ascii_alphanumeric() => {
                if let Some((chars, len)) = entities::match_named(rest) {
                    if !in_attr || !rest.get(len).map_or(false, |n| *n == '=' || n.is_ascii_alphanumeric()) {
                        self.text.extend(chars);
                        self.pos += len;
                        if rest.get(len) == Some(&';') {
                            self.pos += 1;
                        }
                        return;
                    }
                }
                self.text.push('&');
