                Some('>') => {
                    self.state = State::AfterAttributeName;
                    None
                }
                Some(c) => {
                    self.advance();
                    let name = &mut self.tag_name;
                    let idx = self.tag_attrs.len().saturating_sub(1);
                    if self.tag_attrs.is_empty() {
                        self.tag_attrs.push((String::new(), String::new()));
