    fn append_value_char(&mut self, c: char) {
        if c == '\0' {
            self.tag_attrs
                .last_mut()
                .unwrap()
                .1
                .push('\u{FFFD}');
        } else {
            self.tag_attrs.last_mut().unwrap().1.push(c);
        }
    }

    fn consume_attr_reference(&mut self) {
        let rest = &self.input[self.pos..];
        match rest.first() {
            None => self.append_value_char('&'),
            Some('#') => {
                let (value, len) = numeric_reference(&rest[1..]);
                if let Some(c) = value {
                    self.append_value_char(c);
                    self.pos += 1 + len;
                } else {
                    self.append_value_char('&');
                }
            }
            Some(c) if c.is_ascii_alphanumeric() => {
                if let Some((chars, len)) = entities::match_named(rest) {
                    let terminated = rest.get(len) == Some(&';');
                    let blocked = rest.get(len).map_or(false, |n| *n == '=' || n.is_ascii_alphanumeric());
                    if terminated || !blocked {
                        for ch in chars {
                            self.append_value_char(ch);
                        }
                        self.pos += len;
                        if terminated {
                            self.pos += 1;
                        }
                        return;
                    }
                }
                self.append_value_char('&');
            }
            Some(_) => self.append_value_char('&'),
        }
    }

