    /// Shared implementation of the raw text end tag name state: collects the
    /// name and either emits the end tag or pushes the consumed characters
    /// back into the text buffer.
    fn raw_end_tag_name_state(&mut self, finish_state: State) -> Option<Token> {
        loop {
            match self.peek() {
                None => {
                    self.advance();
                    self.state = State::Data;
                    return Some(Token::Eof);
                }
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    let name = self.tag_name.to_ascii_lowercase();
                    if name == self.last_start_tag {
                        // Consume the terminator and emit the end tag.
                        if c == '>' {
                            self.advance();
                        }
                        self.tag_name.clear();
                        self.tag_is_end = false;
                        self.state = State::Data;
                        return Some(Token::EndTag { name });
                    }
                    self.tag_name.clear();
                    self.tag_is_end = false;
                    self.state = finish_state;
                    self.text.push_str("</");
                    self.text.push_str(&name);
                    return None;
                }
                Some(c) => {
                    self.advance();
                    self.tag_name.push(c.to_ascii_lowercase());
                }
            }
        }
    }

    fn raw_text_end_tag_name_state(&mut self) -> Option<Token> {
        self.raw_end_tag_name_state(State::RawText)
    }

