    fn rcdata_state(&mut self) -> Option<Token> {
        loop {
            match self.peek() {
                None => {
                    self.advance();
                    self.state = State::Data;
                    if self.text.is_empty() {
                        return Some(Token::Eof);
                    }
                    let text = std::mem::take(&mut self.text);
                    return Some(Token::Chars(text.chars().collect()));
                }
                Some('&') => {
                    self.advance();
                    self.consume_reference(false);
                }
                Some('<') => {
                    self.advance();
                    self.state = State::RcDataLessThanSign;
                    if self.text.is_empty() {
                        return None;
                    }
                    let text = std::mem::take(&mut self.text);
                    return Some(Token::Chars(text.chars().collect()));
                }
                Some(c) => {
                    self.advance();
                    if c == '\0' {
                        self.text.push('\u{FFFD}');
                    } else {
                        self.text.push(c);
                    }
                }
            }
        }
    }

    fn rcdata_less_than_sign_state(&mut self) -> Option<Token> {
        match self.peek() {
            None => {
                self.advance();
                self.state = State::Data;
                Some(Token::Eof)
            }
            Some('/') => {
                self.advance();
                self.state = State::RcDataEndTagOpen;
                None
            }
            Some(_) => {
                self.state = State::RcData;
                self.text.push('<');
                None
            }
        }
    }

    fn rcdata_end_tag_open_state(&mut self) -> Option<Token> {
        match self.peek() {
            Some(c) if c.is_ascii_alphabetic() => {
                self.advance();
                self.tag_name.clear();
                self.tag_is_end = true;
                self.state = State::RcDataEndTagName;
                None
            }
            Some(_) => {
                self.state = State::RcData;
                self.text.push_str("</");
                None
            }
        }
    }

    fn rcdata_end_tag_name_state(&mut self) -> Option<Token> {
        self.raw_end_tag_name_state(State::RcData)
    }

    fn plaintext_state(&mut self) -> Option<Token> {
        let rest: Vec<char> = self.input[self.pos..].to_vec();
        self.pos = self.input.len();
        self.state = State::Data;
        for c in &rest {
            if *c == '\0' {
                self.text.push('\u{FFFD}');
            } else {
                self.text.push(*c);
            }
        }
        if self.text.is_empty() {
            return Some(Token::Eof);
        }
        let text = std::mem::take(&mut self.text);
        Some(Token::Chars(text.chars().collect()))
    }

    fn cdata_section_state(&mut self) -> Option<Token> {
        loop {
            match self.peek() {
                None => {
                    self.advance();
                    self.state = State::Data;
                    let data = std::mem::take(&mut self.comment);
                    if data.is_empty() {
                        return Some(Token::Eof);
                    }
                    return Some(Token::Comment(data));
                }
                Some(']') => {
                    self.advance();
                    self.state = State::CdataSectionBracket;
                    let data = std::mem::take(&mut self.comment);
                    if data.is_empty() {
                        return None;
                    }
                    return Some(Token::Comment(data));
                }
                Some(c) => {
                    self.advance();
                    self.comment.push(c);
                }
            }
        }
    }

    fn cdata_section_bracket_state(&mut self) -> Option<Token> {
        match self.peek() {
            Some(']') => {
                self.advance();
                self.state = State::CdataSectionEnd;
                None
            }
            Some(_) => {
                self.state = State::CdataSection;
                self.comment.push(']');
                None
            }
            None => {
                self.advance();
                self.state = State::Data;
                let mut data = std::mem::take(&mut self.comment);
                data.push(']');
                Some(Token::Comment(data))
            }
        }
    }

    fn cdata_section_end_state(&mut self) -> Option<Token> {
        match self.peek() {
            Some('>') => {
                self.advance();
                self.state = State::Data;
                None
            }
            Some(']') => {
                self.advance();
                self.comment.push(']');
                None
            }
            Some(_) => {
                self.state = State::CdataSection;
                self.comment.push_str("]]");
                None
            }
            None => {
                self.advance();
                self.state = State::Data;
                let mut data = std::mem::take(&mut self.comment);
                data.push_str("]]");
                Some(Token::Comment(data))
            }
        }
    }
}

fn numeric_reference(s: &[char]) -> (Option<char>, usize) {
    if s.is_empty() {
        return (None, 0);
    }
    let mut i = 0;
    if s[0] == 'x' || s[0] == 'X' {
        i = 1;
    }
    if i >= s.len() || !s[i].is_ascii_digit() {
        return (None, 0);
    }
    let mut value: u32 = 0;
    let mut overflow = false;
    while i < s.len() && s[i].is_ascii_digit() {
        let d = s[i].to_digit(16).unwrap();
        match value.checked_mul(16).and_then(|v| v.checked_add(d)) {
            Some(v) => value = v,
            None => {
                overflow = true;
                break;
            }
        }
        i += 1;
    }
    if overflow || value == 0 {
        return (Some('\u{FFFD}'), i);
    }
    let c = if (0xD800..=0xDFFF).contains(&value) {
        '\u{FFFD}'
    } else {
        match char::from_u32(value) {
            Some(c) => c,
            None => '\u{FFFD}',
        }
    };
    (Some(c), i)
}
