            attrs: Vec::new(),
        }));
        let html = self.stack[0];
        self.tree.append(html, body);
        self.body_ptr = Some(body);
        self.push_element(body);
        self.mode = Mode::InBody;
    }

    fn pop_head(&mut self) {
        if let Some(&top) = self.stack.last() {
            if matches!(self.tree.name(top), Some("head")) {
                self.pop_current();
            }
        }
    }
}
