// ---------------------------------------------------------------------------
// Tree construction
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Debug)]
enum Mode {
    Initial,
    BeforeHtml,
    BeforeHead,
    InHead,
    AfterHead,
    InBody,
    InTable,
    InTableText,
    InCaption,
    InColumnGroup,
    InTableBody,
    InRow,
    InCell,
    InSelect,
    InSelectInTable,
    InTemplate,
    AfterBody,
    AfterAfterBody,
    InFrameset,
    AfterFrameset,
    AfterAfterFrameset,
}

#[derive(Clone)]
enum ActiveFormat {
    Element { node: usize, name: String },
    Marker,
}

const HEAD_ELEMENTS: &[&str] = &[
    "base", "basefont", "bgsound", "link", "meta", "noframes", "script", "style", "template",
    "title",
];

fn is_head_element(name: &str) -> bool {
    HEAD_ELEMENTS.contains(&name)
}

pub struct TreeBuilder {
    tree: Tree,
    stack: Vec<usize>,
    formats: Vec<ActiveFormat>,
    mode: Mode,
    head_ptr: Option<usize>,
    body_ptr: Option<usize>,
    form_ptr: Option<usize>,
    table_text: Vec<char>,
    table_text_ws: bool,
    foster_parenting: bool,
    drop_top_level_comments: bool,
}

/// Elements that are allowed in the head; everything else is moved to the body.
fn adjust_mode(name: &str, mode: Mode) -> Mode {
    match name {
        "caption" | "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th" => Mode::InTable,
        "option" | "optgroup" => Mode::InSelect,
        _ => mode,
    }
}

impl TreeBuilder {
    pub fn new() -> TreeBuilder {
        let mut tree = Tree {
            nodes: Vec::new(),
            document: 0,
        };
        tree.nodes.push(Node {
            data: NodeData::Document,
            parent: None,
            children: Vec::new(),
        });
        TreeBuilder {
            tree,
            stack: Vec::new(),
            formats: Vec::new(),
            mode: Mode::Initial,
            head_ptr: None,
            body_ptr: None,
            form_ptr: None,
            table_text: Vec::new(),
            table_text_ws: true,
            foster_parenting: false,
            drop_top_level_comments: false,
        }
    }

    pub fn build(input: Vec<char>) -> Tree {
        let mut b = TreeBuilder::new();
        b.run(input);
        b.tree
    }

    fn create(&mut self, data: NodeData) -> usize {
        self.tree.new_node(data)
    }

    fn current(&self) -> usize {
        *self.stack.last().unwrap_or(&self.tree.document)
    }

    fn push_element(&mut self, node: usize) {
        self.stack.push(node);
    }

    fn pop_current(&mut self) {
        if let Some(node) = self.stack.pop() {
            self.remove_from_formats(node);
        }
    }

    fn remove_from_formats(&mut self, node: usize) {
        self.formats.retain(|f| match f {
            ActiveFormat::Element { node: n, .. } => *n != node,
            _ => true,
        });
    }

    fn insert_at_current(&mut self, node: usize) {
        let place = self.appropriate_place();
        self.tree.append(place, node);
    }

    /// "appropriate place for inserting a node", including foster parenting.
    fn appropriate_place(&mut self) -> usize {
        let mut target = self.current();
        if !self.foster_parenting {
            return target;
        }
        // Foster parenting: insert before the table.
        loop {
            let name = self.tree.name(target).unwrap_or("").to_string();
            match name.as_str() {
                "table" | "tbody" | "tfoot" | "thead" | "tr" => {
                    let last_table = self
                        .stack
                        .iter()
                        .rev()
                        .find(|&&n| matches!(self.tree.name(n), Some("table")));
                    match last_table {
                        None => {
                            // Insert into the parent of the table element.
                            let parent = self.tree.parent(target).unwrap_or(self.tree.document);
                            return parent;
                        }
                        Some(&table) => {
                            // Create a temp child to hold the content.
                            let place = self.tree.parent(table).unwrap_or(self.tree.document);
                            return place;
                        }
                    }
                }
                _ => return target,
            }
        }
    }

    /// Insert `node` before the table element (foster parenting) when needed.
    fn insert_with_foster(&mut self, node: usize) {
        if self.foster_parenting {
            let target = self.current();
            let name = self.tree.name(target).unwrap_or("").to_string();
            if matches!(name.as_str(), "table" | "tbody" | "tfoot" | "thead" | "tr") {
                // Insert before the table element.
                let table = *self
                    .stack
                    .iter()
                    .rev()
                    .find(|&&n| matches!(self.tree.name(n), Some("table")))
                    .unwrap_or(&target);
                let place = self.tree.parent(table).unwrap_or(self.tree.document);
                // Insert immediately before the table in its parent.
                let idx = self.tree.nodes[place]
                    .children
                    .iter()
                    .position(|&c| c == table);
                match idx {
                    Some(i) => {
                        self.tree.nodes[node].parent = Some(place);
                        self.tree.nodes[place].children.insert(i, node);
                        return;
                    }
                    None => {}
                }
            }
        }
        let place = self.appropriate_place();
        self.tree.append(place, node);
    }

    fn run(&mut self, input: Vec<char>) {
        let mut tok = Tokenizer::new(input);
        loop {
            let token = tok.next_token();
            let eof = token == Token::Eof;
            self.process(token);
            if eof {
                break;
            }
        }
    }

    fn process(&mut self, token: Token) {
        match token {
            Token::Eof => self.process_eof(),
            Token::Doctype => {}
            Token::Comment(data) => self.process_comment(data),
            Token::Chars(chars) => self.process_chars(chars),
            Token::StartTag {
                name,
                attrs,
                self_closing,
            } => self.process_start_tag(name, attrs, self_closing),
            Token::EndTag { name } => self.process_end_tag(name),
        }
    }

    fn process_eof(&mut self) {
        match self.mode {
            Mode::Initial | Mode::BeforeHtml | Mode::BeforeHead => {
                self.insert_implicit_head();
                self.mode = Mode::InHead;
                self.process_eof();
            }
            Mode::InHead => {
                self.pop_head();
                self.mode = Mode::AfterHead;
                self.process_eof();
            }
            Mode::AfterHead => {
                self.insert_implicit_body();
                self.mode = Mode::InBody;
                self.process_eof();
            }
            Mode::AfterBody | Mode::AfterAfterBody => {}
            _ => {}
        }
    }

    fn process_comment(&mut self, data: Option<String>) {
        let node = self.create(NodeData::Comment(data.unwrap_or_default()));
        match self.mode {
            Mode::Initial | Mode::BeforeHtml | Mode::BeforeHead => {
                self.tree.append(self.tree.document, node);
            }
            Mode::AfterBody | Mode::AfterAfterBody => {
                let html = self.stack.first().copied().unwrap_or(self.tree.document);
                self.tree.append(html, node);
            }
            _ => {
                let place = self.current();
                self.tree.append(place, node);
            }
        }
    }

    fn process_chars(&mut self, chars: Vec<char>) {
        match self.mode {
            Mode::Initial | Mode::BeforeHtml => {
                // Whitespace is ignored; anything else creates the html element.
                if chars.iter().any(|c| !is_ws(*c)) {
                    self.insert_implicit_html();
                    self.mode = Mode::BeforeHead;
                    self.process_chars(chars);
                }
            }
            Mode::BeforeHead => {
                if chars.iter().any(|c| !is_ws(*c)) {
                    self.insert_implicit_head();
                    self.mode = Mode::InHead;
                    self.process_chars(chars);
                }
            }
            Mode::InHead => {
                if chars.iter().all(|c| is_ws(*c)) {
                    let node = self.create(NodeData::Text(String::from_iter(chars)));
                    let head = self.head_ptr.unwrap();
                    self.tree.append(head, node);
                } else {
                    self.pop_head();
                    self.mode = Mode::AfterHead;
                    self.process_chars(chars);
                }
            }
            Mode::AfterHead => {
                self.insert_implicit_body();
                self.mode = Mode::InBody;
                self.process_chars(chars);
            }
            Mode::AfterBody | Mode::AfterAfterBody => {
                if let Some(body) = self.body_ptr {
                    let node = self.create(NodeData::Text(String::from_iter(chars)));
                    self.tree.append(body, node);
                }
            }
            Mode::InTableText => {
                for c in &chars {
                    self.table_text.push(*c);
                    if !is_ws(*c) {
                        self.table_text_ws = false;
                    }
                }
            }
            _ => {
                self.insert_text_chars(chars);
            }
        }
    }

    fn insert_text_chars(&mut self, chars: Vec<char>) {
        // Reconstruct active formatting elements first.
        self.reconstruct_formatting();
        let text = String::from_iter(chars);
        let node = self.create(NodeData::Text(text));
        self.insert_with_foster(node);
    }

    fn insert_implicit_html(&mut self) {
        let html = self.create(NodeData::Element(ElementData {
            name: QualName::html("html"),
            attrs: Vec::new(),
        }));
        self.tree.append(self.tree.document, html);
        self.push_element(html);
        self.stack.insert(0, html);
        self.stack.remove(0);
    }

    fn insert_implicit_head(&mut self) {
        // Ensure html exists.
        if self.stack.is_empty() {
            self.insert_implicit_html();
            self.mode = Mode::BeforeHtml;
        }
        let head = self.create(NodeData::Element(ElementData {
            name: QualName::html("head"),
            attrs: Vec::new(),
        }));
        let html = self.stack[0];
        self.tree.append(html, head);
        self.head_ptr = Some(head);
        self.push_element(head);
        self.mode = Mode::InHead;
    }

    fn insert_implicit_body(&mut self) {
        if self.head_ptr.is_none() {
            self.insert_implicit_head();
            self.mode = Mode::AfterHead;
        }
        if !self.stack.is_empty() && matches!(self.tree.name(self.current()), Some("head")) {
            self.pop_current();
        }
        let body = self.create(NodeData::Element(ElementData {
            name: QualName::html("body"),
            attrs: Vec::new(),
        }));
        let html = self.stack[0];
        self.tree.append(html, body);
        self.body_ptr = Some(body);
        self.push_element(body);
        self.mode = Mode::InBody;
    }

    fn pop_head(&mut self) {
        if let Some(&top) = self.stack.last() {
            if matches!(self.tree.name(top), Some("head")) {
                self.pop_current();
            }
        }
    }
}
