impl TreeBuilder {
    // ---- helpers -----------------------------------------------------------

    fn reconstruct_formatting(&mut self) {
        if self.formats.is_empty() {
            return;
        }
        // Find the first entry that is neither a marker nor on the stack.
        let mut start = None;
        for (idx, f) in self.formats.iter().enumerate() {
            match f {
                ActiveFormat::Marker => {}
                ActiveFormat::Element { node, .. } => {
                    if !self.stack.contains(node) {
                        start = Some(idx);
                        break;
                    }
                }
            }
        }
        let Some(mut idx) = start else { return };
        while idx < self.formats.len() {
            let name = match &self.formats[idx] {
                ActiveFormat::Element { name, .. } => name.clone(),
                ActiveFormat::Marker => {
                    idx += 1;
                    continue;
                }
            };
            let node = self.create(NodeData::Element(ElementData {
                name: QualName::html(&name),
                attrs: Vec::new(),
            }));
            let place = self.current();
            self.tree.append(place, node);
            self.push_element(node);
            if let ActiveFormat::Element { node: ref mut n, .. } = self.formats[idx] {
                *n = node;
            }
            idx += 1;
        }
    }

    fn remove_format_by_name(&mut self, name: &str) {
        for i in (0..self.formats.len()).rev() {
            if let ActiveFormat::Element { name: n, .. } = &self.formats[i] {
                if n == name {
                    self.formats.remove(i);
                    return;
                }
            }
        }
    }

    fn mark_format(&mut self, name: &str, node: usize) {
        // Remove an existing entry with the same tag name above the last marker.
        for i in (0..self.formats.len()).rev() {
            match &self.formats[i] {
                ActiveFormat::Marker => break,
                ActiveFormat::Element { name: n, .. } if n == name => {
                    self.formats.remove(i);
                    break;
                }
                _ => {}
            }
        }
        self.formats.push(ActiveFormat::Element {
            node,
            name: name.to_string(),
        });
    }

    fn in_scope(&self, name: &str) -> bool {
        for &n in self.stack.iter().rev() {
            let nname = self.tree.name(n).unwrap_or("");
            if nname == name {
                return true;
            }
            if matches!(nname, "applet" | "caption" | "html" | "table" | "td" | "th" | "marquee"
                | "object" | "template" | "button" | "keygen" | "math" | "mi" | "mo" | "mn" | "ms"
                | "mtext" | "select" | "svg" | "foreignObject" | "title" | "textarea")
            {
                return false;
            }
        }
        false
    }

    fn has_in_list_item_scope(&self, name: &str) -> bool {
        for &n in self.stack.iter().rev() {
            let nname = self.tree.name(n).unwrap_or("");
            if nname == name {
                return true;
            }
            if matches!(nname, "ol" | "ul") {
                return false;
            }
        }
        false
    }

    fn generate_implied_end_tags(&mut self, except: Option<&str>) {
        loop {
            let name = match self.stack.last() {
                Some(&n) => self.tree.name(n).unwrap_or("").to_string(),
                None => return,
            };
            let implied = match name.as_str() {
                "dd" | "dt" | "li" | "optgroup" | "option" | "p" | "rb" | "rp" | "rt" | "rtc" => true,
                "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => false,
                _ => false,
            };
            if !implied || except == Some(name.as_str()) {
                return;
            }
            self.pop_current();
        }
    }

    fn adoption_agency(&mut self, subject: &str) -> bool {
        // Find the formatting element in the active list.
        let mut f_idx = None;
        for i in (0..self.formats.len()).rev() {
            match &self.formats[i] {
                ActiveFormat::Marker => break,
                ActiveFormat::Element { name, .. } if name == subject => {
                    f_idx = Some(i);
                    break;
                }
                _ => {}
            }
        }
        let Some(f_idx) = f_idx else { return false };
        let f_node = match &self.formats[f_idx] {
            ActiveFormat::Element { node, .. } => *node,
            _ => return false,
        };
        // Find the deepest open special element below the formatting element.
        let f_pos = self.stack.iter().position(|&n| n == f_node);
        let furthest = match f_pos {
            None => None,
            Some(p) => self.stack[p + 1..]
                .iter()
                .filter(|&&n| {
                    self.tree
                        .name(n)
                        .map(|n| is_special(n))
                        .unwrap_or(false)
                })
                .next_back()
                .copied(),
        };
        let Some(b) = furthest else {
            // Pop the stack until the formatting element is popped.
            loop {
                let top = match self.stack.last() {
                    Some(&n) => n,
                    None => break,
                };
                let popped = self.pop_current();
                if top == f_node || popped {
                    break;
                }
            }
            self.remove_format_by_name(subject);
            return true;
        };
        let common_ancestor = match self.stack.iter().position(|&n| n == b) {
            Some(0) => self.stack[0],
            Some(p) => self.stack[p - 1],
            None => return true,
        };
        // Reparent furthest block under the common ancestor.
        if self.tree.parent(b) != Some(common_ancestor) {
            self.tree.detach(b);
            self.tree.append(common_ancestor, b);
        }
        // Insert the bookmark: we reuse the position after b in the parent.
        let mut last_node = b;
        loop {
            let node = match self.stack.iter().position(|&n| n == last_node) {
                Some(0) => break,
                Some(p) => self.stack[p - 1],
                None => break,
            };
            if node == f_node {
                break;
            }
            // Clone node and move its contents into the clone.
            let name = self.tree.name(node).unwrap_or("").to_string();
            let clone = self.create(NodeData::Element(ElementData {
                name: QualName::html(&name),
                attrs: self
                    .tree
                    .element(node)
                    .map(|e| e.attrs.clone())
                    .unwrap_or_default(),
            }));
            // Insert clone after last_node in the common ancestor.
            self.tree.insert_after(common_ancestor, last_node, clone);
            // Move node's children to clone, then drop node.
            let children: Vec<usize> = self.tree.children(node).to_vec();
            for c in children {
                self.tree.detach(c);
                self.tree.append(clone, c);
            }
            self.remove_format_by_name(&name);
            self.formats.push(ActiveFormat::Element {
                node: clone,
                name: name.clone(),
            });
            self.pop_current();
            last_node = clone;
        }
        // Remove formatting element from the list and re-insert after the clone.
        self.remove_format_by_name(subject);
        // Insert new element for subject after last_node.
        let new_node = self.create(NodeData::Element(ElementData {
            name: QualName::html(subject),
            attrs: self
                .tree
                .element(f_node)
                .map(|e| e.attrs.clone())
                .unwrap_or_default(),
        }));
        self.tree.insert_after(common_ancestor, last_node, new_node);
        self.tree.detach(f_node);
        // Move furthest block into the new element.
        self.tree.detach(b);
        self.tree.append(new_node, b);
        // Pop down to and including furthest block, then push the new element.
        loop {
            match self.stack.last() {
                Some(&n) if n != b => {
                    self.pop_current();
                }
                _ => break,
            }
        }
        self.pop_current();
        self.push_element(new_node);
        self.formats.push(ActiveFormat::Element {
            node: new_node,
            name: subject.to_string(),
        });
        true
    }

    fn pop_until(&mut self, name: &str) {
        loop {
            match self.stack.last() {
                Some(&n) => {
                    let nname = self.tree.name(n).unwrap_or("").to_string();
                    self.pop_current();
                    if nname == name {
                        return;
                    }
                    if matches!(nname.as_str(), "html" | "body") {
                        return;
                    }
                }
                None => return,
            }
        }
    }

    fn insert_element(&mut self, name: &str, attrs: Vec<(String, String)>, ns: Option<&str>) {
        self.reconstruct_formatting();
        let qname = match ns {
            Some(NS_SVG) => QualName {
                ns: Some(NS_SVG.to_string()),
                local: svg_element_name(name),
            },
            Some(NS_MATHML) => QualName {
                ns: Some(NS_MATHML.to_string()),
                local: name.to_string(),
            },
            _ => QualName::html(name),
        };
        let mut data = ElementData {
            name: qname,
            attrs: Vec::new(),
        };
        for (k, v) in attrs {
            insert_attr(&mut data, &k, &v, ns);
        }
        let node = self.create(NodeData::Element(data));
        self.insert_with_foster(node);
        if is_void(name) && ns.is_none() {
            return;
        }
        if self_closing_ok(name, ns) {
            return;
        }
        self.push_element(node);
        if is_formatting(name) && ns.is_none() {
            self.mark_format(name, node);
        }
        self.mode = match self.mode {
            Mode::InBody => adjust_mode(name, Mode::InBody),
            m => m,
        };
        // Set raw text mode on the tokenizer side is handled by the caller.
    }

    fn merge_attrs(&mut self, node: usize, attrs: Vec<(String, String)>) {
        let ns: Option<&str> = None;
        if let Some(e) = self.tree.element_mut(node) {
            for (k, v) in attrs {
                let mut data = ElementData {
                    name: e.name.clone(),
                    attrs: std::mem::take(&mut e.attrs),
                };
                insert_attr(&mut data, &k, &v, ns);
                e.attrs = data.attrs;
            }
        }
    }

    fn insert_implicit_body_merge(&mut self, attrs: Vec<(String, String)>) {
        match self.body_ptr {
            Some(body) => {
                self.merge_attrs(body, attrs);
                self.mode = Mode::InBody;
                self.push_element(body);
            }
            None => {
                self.insert_implicit_body();
                if let Some(body) = self.body_ptr {
                    self.merge_attrs(body, attrs);
                }
            }
        }
    }
}

fn self_closing_ok(name: &str, ns: Option<&str>) -> bool {
    if ns.is_some() {
        return true;
    }
    is_void(name)
}

fn insert_attr(data: &mut ElementData, name: &str, value: &str, ns: Option<&str>) {
    let (mut nsn, mut local) = (None, name.to_string());
    if ns == Some(NS_SVG) || ns == Some(NS_MATHML) {
        // Adjust foreign attributes.
        if let Some(rest) = name.strip_prefix("xlink:") {
            nsn = Some(NS_XLINK.to_string());
            local = rest.to_string();
        } else if let Some(rest) = name.strip_prefix("xml:") {
            nsn = Some(NS_XML.to_string());
            local = rest.to_string();
        } else if name == "xmlns" {
            nsn = Some(NS_XMLNS.to_string());
            local = "xmlns".to_string();
        } else if let Some(rest) = name.strip_prefix("xmlns:") {
            nsn = Some(NS_XMLNS.to_string());
            local = rest.to_string();
        }
        if ns == Some(NS_SVG) {
            local = svg_attribute_name(&local).to_string();
        } else if local == "definitionurl" {
            local = "definitionURL".to_string();
        }
    }
    let key = QualName { ns: nsn, local };
    match data.attrs.iter_mut().find(|(k, _)| *k == key) {
        Some(slot) => slot.1 = value.to_string(),
        None => {
            let pos = data
                .attrs
                .binary_search_by(|(k, _)| k.cmp(&key))
                .unwrap_or_else(|e| e);
            data.attrs.insert(pos, (key, value.to_string()));
        }
    }
}
