                "optgroup" => {
                    if self.tree.name(self.current()) == Some("option") {
                        self.pop_current();
                    }
                    if self.tree.name(self.current()) == Some("optgroup") {
                        self.pop_current();
                    }
                }
                "option" => {
                    if self.tree.name(self.current()) == Some("option") {
                        self.pop_current();
                    }
                }
                "select" => {
                    self.pop_until("select");
                    self.mode = Mode::InBody;
                }
                "caption" | "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th" => {
                    self.mode = Mode::InTable;
                    self.process_end_tag(name);
                }
                _ => {}
            },
            Mode::AfterBody | Mode::AfterAfterBody => {
                if name == "html" {
                    self.mode = Mode::AfterAfterBody;
                    return;
                }
                self.mode = Mode::InBody;
                self.process_end_tag(name);
            }
            _ => self.in_body_end(name),
        }
    }

    fn in_body_end(&mut self, name: String) {
        match name.as_str() {
            "body" => {
                self.mode = Mode::AfterBody;
                return;
            }
            "html" => {
                self.mode = Mode::AfterBody;
                return;
            }
            "p" => {
                if self.in_scope("p") {
                    self.generate_implied_end_tags(Some("p"));
                    self.pop_current();
                    return;
                }
            }
            "li" | "dd" | "dt" | "optgroup" | "option" | "rb" | "rp" | "rt" | "rtc" => {
                if self.in_scope(&name) {
                    self.generate_implied_end_tags(Some(&name));
                    self.pop_current();
                    return;
                }
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if self.in_scope(&name) {
                    self.generate_implied_end_tags(None);
                    self.pop_current();
                    return;
                }
            }
            "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th" | "caption"
            | "colgroup" | "col" | "select" | "optgroup" | "option" => {
                if self.in_scope(&name) {
                    self.pop_until(&name);
                    self.mode = Mode::InBody;
                    return;
                }
            }
            "a" | "b" | "big" | "code" | "em" | "font" | "i" | "nobr" | "s" | "small"
            | "strike" | "strong" | "tt" | "u" => {
                if self.adoption_agency(&name) {
                    return;
                }
            }
            "applet" | "marquee" | "object" => {
                if self.in_scope(&name) {
                    self.generate_implied_end_tags(None);
                    self.pop_current();
                    self.clear_formats_to_marker();
                    return;
                }
            }
            "br" => {
                return;
            }
            _ => {}
        }
        // Any other end tag: pop until we find a matching element.
        for (i, &n) in self.stack.iter().enumerate().rev() {
            let nname = self.tree.name(n).unwrap_or("").to_string();
            if nname == name {
                self.generate_implied_end_tags(Some(&name));
                while self.stack.len() > i + 1 {
                    self.pop_current();
                }
                self.pop_current();
                return;
            }
            if is_special(&nname) {
                return;
            }
        }
    }

    fn clear_formats_to_marker(&mut self) {
        while let Some(f) = self.formats.pop() {
            if matches!(f, ActiveFormat::Marker) {
                break;
            }
        }
    }
}
