            if nname == name {
                self.generate_implied_end_tags(Some(&name));
                while self.stack.len() > i + 1 {
                    self.pop_current();
                }
                self.pop_current();
                return;
            }
            if is_special(&nname) {
                return;
            }
        }
    }

    fn clear_formats_to_marker(&mut self) {
        while let Some(f) = self.formats.pop() {
            if matches!(f, ActiveFormat::Marker) {
                break;
            }
        }
    }
}
