use crate::html::{ElementData, NodeData, QualName, Tree, NS_SVG, NS_MATHML};

pub fn escape_text(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '\u{A0}' => out.push_str("&nbsp;"),
            c => out.push(c),
        }
    }
}

pub fn escape_attr(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            '\u{A0}' => out.push_str("&nbsp;"),
            c => out.push(c),
        }
    }
}

fn ns_prefix(ns: &Option<String>, local: &str) -> String {
    match ns.as_deref() {
        Some(crate::html::NS_XLINK) => format!("xlink:{}", local),
        Some(crate::html::NS_XML) => format!("xml:{}", local),
        Some(crate::html::NS_XMLNS) => {
            if local == "xmlns" {
                "xmlns".to_string()
            } else {
                format!("xmlns:{}", local)
            }
        }
        _ => local.to_string(),
    }
}

pub fn serialize(tree: &Tree, node: usize, out: &mut String) {
    match tree.data(node) {
        NodeData::Document => {
            for &c in tree.children(node) {
                serialize(tree, c, out);
            }
        }
        NodeData::Text(t) => out.push_str(t),
        NodeData::Comment(c) => {
            out.push_str("<!--");
            out.push_str(c);
            out.push_str("-->");
        }
        NodeData::Doctype(_) => {}
        NodeData::Element(e) => {
            out.push('<');
            out.push_str(&ns_prefix(&e.name.ns, &e.name.local));
            for (k, v) in &e.attrs {
                out.push(' ');
                out.push_str(&ns_prefix(&k.ns, &k.local));
                out.push_str("=\"");
                escape_attr(v, out);
                out.push('"');
            }
            out.push('>');
            let raw = is_raw(tree, node);
            for &c in tree.children(node) {
                if raw {
                    if let NodeData::Text(t) = tree.data(c) {
                        out.push_str(t);
                        continue;
                    }
                }
                serialize(tree, c, out);
            }
            if !is_void(tree, node) {
                out.push_str("</");
                out.push_str(&ns_prefix(&e.name.ns, &e.name.local));
                out.push('>');
            }
        }
    }
}

fn is_void(tree: &Tree, node: usize) -> bool {
    match tree.element(node) {
        Some(e) => e.name.ns.is_none() && crate::html::is_void_tag(&e.name.local),
        None => false,
    }
}

fn is_raw(tree: &Tree, node: usize) -> bool {
    match tree.element(node) {
        Some(e) => {
            e.name.ns.is_none()
                && matches!(
                    e.name.local.as_str(),
                    "script" | "style" | "xmp" | "iframe" | "noembed" | "noframes" | "plaintext"
                )
        }
        None => false,
    }
}

/// Pretty printing, following the line breaking behaviour of the original.
const BLOCK_TAGS: &[&str] = &[
    "address", "area", "article", "aside", "base", "basefont", "bgsound", "blockquote", "br",
    "body", "caption", "col", "colgroup", "dd", "details", "dialog", "div", "dl", "dt", "embed",
    "fieldset", "figcaption", "figure", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6",
    "head", "header", "hgroup", "hr", "html", "isindex", "keygen", "legend", "li", "link",
    "listing", "main", "marquee", "menu", "meta", "nav", "noembed", "noframes", "nobr", "nextid",
    "ol", "optgroup", "option", "p", "param", "plaintext", "pre", "rp", "rt", "search",
    "section", "source", "spacer", "strike", "style", "summary", "table", "tbody", "td",
    "template", "tfoot", "th", "thead", "time", "title", "tr", "track", "ul", "xmp",
];

pub fn is_block(name: &str) -> bool {
    BLOCK_TAGS.contains(&name)
}

pub fn serialize_pretty(tree: &Tree, root: usize, out: &mut String) {
    pretty_node(tree, root, 0, out, false);
    out.push('\n');
}

fn indent(out: &mut String, depth: usize) {
    for _ in 0..depth {
        out.push_str("  ");
    }
}

fn has_prev_block_sibling(tree: &Tree, node: usize) -> bool {
    if let Some(p) = tree.parent(node) {
        let children = tree.children(p);
        if let Some(idx) = children.iter().position(|&c| c == node) {
            if idx > 0 {
                let prev = children[idx - 1];
                if let Some(e) = tree.element(prev) {
                    if e.name.ns.is_none() && is_block(&e.name.local) {
                        return true;
                    }
                }
            }
        }
    }
    false
}

fn first_child_of(tree: &Tree, node: usize) -> Option<usize> {
    tree.children(node).first().copied()
}

fn is_block_elem(tree: &Tree, node: usize) -> bool {
    match tree.element(node) {
        Some(e) => e.name.ns.is_none() && is_block(&e.name.local),
        None => false,
    }
}

fn prev_sibling_node(tree: &Tree, node: usize) -> Option<usize> {
    let p = tree.parent(node)?;
    let children = tree.children(p);
    let idx = children.iter().position(|&c| c == node)?;
    if idx == 0 {
        None
    } else {
        Some(children[idx - 1])
    }
}

fn prev_meaningful_sibling(tree: &Tree, node: usize) -> Option<usize> {
    let p = tree.parent(node)?;
    let children = tree.children(p);
    let idx = children.iter().position(|&c| c == node)?;
    if idx == 0 {
        None
    } else {
        Some(children[idx - 1])
    }
}

fn break_before(
    tree: &Tree,
    node: usize,
    depth: usize,
    out: &mut String,
) {
    out.push('\n');
    indent(out, depth);
}

fn pretty_node(tree: &Tree, node: usize, depth: usize, out: &mut String, _in_block: bool) {
    match tree.data(node) {
        NodeData::Text(t) => escape_text(t, out),
        NodeData::Comment(c) => {
            out.push_str("<!--");
            out.push_str(c);
            out.push_str("-->");
        }
        NodeData::Document => {
            for &c in tree.children(node) {
                pretty_node(tree, c, depth, out, _in_block);
            }
        }
        NodeData::Doctype(_) => {}
        NodeData::Element(e) => {
            let block = e.name.ns.is_none() && is_block(&e.name.local);
            if block {
                out.push('\n');
                indent(out, depth);
            }
            out.push('<');
            out.push_str(&ns_prefix(&e.name.ns, &e.name.local));
            for (k, v) in &e.attrs {
                out.push(' ');
                out.push_str(&ns_prefix(&k.ns, &k.local));
                out.push_str("=\"");
                escape_attr(v, out);
                out.push('"');
            }
            out.push('>');
            let raw = is_raw(tree, node);
            // Decide the depth for children.
            let child_depth = depth + 1;
            let prev_block_ancestor = {
                let mut any = false;
                let mut n = tree.parent(node);
                while let Some(p) = n {
                    if is_block_elem(tree, p) && has_prev_block_sibling(tree, p) {
                        any = true;
                        break;
                    }
                    n = tree.parent(p);
                }
                any
            };
            for (i, &c) in tree.children(node).to_vec().iter().enumerate() {
                let cblock = is_block_elem(tree, c);
                let prev = if i == 0 { None } else { Some(tree.children(node)[i - 1]) };
                let prev_block = match prev {
                    Some(p) => is_block_elem(tree, p),
                    None => false,
                };
                let mut need = cblock || prev_block;
                if !need && !cblock {
                    // first child / after a comment, and an ancestor had a
                    // preceding block sibling
                    if prev.is_none() || is_comment(tree, prev.unwrap()) {
                        if prev_block_ancestor {
                            need = !matches!(tree.data(c), NodeData::Comment(_));
                        }
                    }
                }
                if need {
                    out.push('\n');
                    indent(out, child_depth);
                }
                if raw {
                    if let NodeData::Text(t) = tree.data(c) {
                        out.push_str(t);
                        continue;
                    }
                }
                pretty_node(tree, c, child_depth, out, prev_block_ancestor);
            }
            if block {
                out.push('\n');
                indent(out, depth);
            }
            if !is_void(tree, node) {
                out.push_str("</");
                out.push_str(&ns_prefix(&e.name.ns, &e.name.local));
                out.push('>');
            }
        }
    }
}

fn is_comment(tree: &Tree, node: usize) -> bool {
    matches!(tree.data(node), NodeData::Comment(_))
}
