/// Minimal WHATWG-style URL parsing and resolution, sufficient for the
/// behaviours observed in the reference implementation.

#[derive(Clone, Debug, PartialEq)]
pub struct Url {
    pub scheme: String,
    pub username: String,
    pub password: Option<String>,
    pub host: Option<String>,
    pub port: Option<u16>,
    pub path: String,
    pub query: Option<String>,
    pub fragment: Option<String>,
}

fn default_port(scheme: &str) -> Option<u16> {
    match scheme {
        "http" | "ws" => Some(80),
        "https" | "wss" => Some(443),
        "ftp" => Some(21),
        "file" => None,
        _ => None,
    }
}

pub fn is_special(scheme: &str) -> bool {
    matches!(scheme, "http" | "https" | "ws" | "wss" | "ftp" | "file")
}

pub fn parse(input: &str) -> Option<Url> {
    let s: Vec<char> = input.chars().collect();
    // scheme
    let mut i = 0;
    if !s.is_empty() && s[0].is_ascii_alphabetic() {
        i = 1;
        while i < s.len() && (s[i].is_ascii_alphanumeric() || s[i] == '+' || s[i] == '-' || s[i] == '.')
        {
            i += 1;
        }
    }
    if i >= s.len() || s[i] != ':' {
        return None;
    }
    let scheme: String = s[..i].iter().collect::<String>().to_ascii_lowercase();
    let rest: Vec<char> = s[i + 1..].to_vec();
    if is_special(&scheme) {
        let mut r = &rest[..];
        // slashes
        let mut slashes = 0;
        while let Some(&c) = r.first() {
            if c == '/' || c == '\\' {
                slashes += 1;
                r = &r[1..];
            } else {
                break;
            }
        }
        if slashes == 0 && scheme != "file" {
            return None;
        }
        // authority
        let mut j = 0;
        while j < r.len() && r[j] != '/' && r[j] != '\\' && r[j] != '?' && r[j] != '#' {
            j += 1;
        }
        let authority: String = r[..j].iter().collect();
        let mut r = &r[j..];
        let (userinfo, hostport) = match authority.rfind('@') {
            Some(p) => (Some(authority[..p].to_string()), authority[p + 1..].to_string()),
            None => (None, authority.clone()),
        };
        let (host, port) = match hostport.rfind(':') {
            Some(p) if !hostport[p + 1..].contains(']') => (
                hostport[..p].to_string(),
                hostport[p + 1..].parse::<u16>().ok(),
            ),
            _ => (hostport.clone(), None),
        };
        let host = host.to_ascii_lowercase();
        let port = match port {
            Some(p) if Some(p) == default_port(&scheme) => None,
            other => other,
        };
        // path, query, fragment
        let mut path = String::new();
        let mut query = None;
        let mut fragment = None;
        let mut k = 0;
        while k < r.len() && r[k] != '?' && r[k] != '#' {
            k += 1;
        }
        let mut rest2 = &r[..];
        if k > 0 {
            path = r[..k].iter().collect();
            rest2 = &r[k..];
        }
        if let Some(&c) = rest2.first() {
            if c == '?' {
                let mut m = 1;
                while m < rest2.len() && rest2[m] != '#' {
                    m += 1;
                }
                query = Some(rest2[1..m].iter().collect());
                rest2 = &rest2[m..];
            }
        }
        if let Some(&c) = rest2.first() {
            if c == '#' {
                fragment = Some(rest2[1..].iter().collect());
            }
        }
        let path = normalize_path(&path, true);
        Some(Url {
            scheme,
            username: userinfo.map(|u| u).unwrap_or_default(),
            password: None,
            host: Some(host),
            port,
            path,
            query,
            fragment,
        })
    } else {
        // Opaque path
        let rest: String = rest.iter().collect();
        let (path, query, fragment) = split_path_query_fragment(&rest);
        Some(Url {
            scheme,
            username: String::new(),
            password: None,
            host: None,
            port: None,
            path,
            query,
            fragment,
        })
    }
}

fn split_path_query_fragment(s: &str) -> (String, Option<String>, Option<String>) {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() && chars[i] != '?' && chars[i] != '#' {
        i += 1;
    }
    let path: String = chars[..i].iter().collect();
    let mut rest = &chars[i..];
    let mut query = None;
    let mut fragment = None;
    if let Some(&c) = rest.first() {
        if c == '?' {
            let mut m = 1;
            while m < rest.len() && rest[m] != '#' {
                m += 1;
            }
            query = Some(rest[1..m].iter().collect());
            rest = &rest[m..];
        }
    }
    if let Some(&c) = rest.first() {
        if c == '#' {
            fragment = Some(rest[1..].iter().collect());
        }
    }
    (path, query, fragment)
}

fn normalize_path(path: &str, special: bool) -> String {
    let mut p: Vec<char> = path.chars().collect();
    if special {
        for c in p.iter_mut() {
            if *c == '\\' {
                *c = '/';
            }
        }
    }
    let segments: Vec<String> = String::from_iter(p.iter())
        .split('/')
        .map(|s| s.to_string())
        .collect();
    let mut out: Vec<String> = Vec::new();
    for seg in segments {
        match seg.as_str() {
            "." => {}
            ".." => {
                out.pop();
            }
            s => out.push(s.to_string()),
        }
    }
    let mut result = out.join("/");
    if result.is_empty() || !result.starts_with('/') {
        result = format!("/{}", result);
    }
    result
}

pub fn to_string(u: &Url) -> String {
    let mut out = String::new();
    out.push_str(&u.scheme);
    out.push(':');
    if let Some(host) = &u.host {
        out.push_str("//");
        if !u.username.is_empty() {
            out.push_str(&u.username);
            out.push('@');
        }
        out.push_str(host);
        if let Some(p) = u.port {
            out.push(':');
            out.push_str(&p.to_string());
        }
    }
    out.push_str(&u.path);
    if let Some(q) = &u.query {
        out.push('?');
        out.push_str(q);
    }
    if let Some(f) = &u.fragment {
        out.push('#');
        out.push_str(f);
    }
    out
}

/// Percent-encode according to the WHATWG path/query/fragment sets.
fn encode_component(s: &str, extra: &[char], preserve: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if preserve.contains(c) && !extra.contains(&c) {
            out.push(c);
        } else if extra.contains(&c) || (c as u32) <= 0x20 || (c as u32) >= 0x7f || c == '"' {
            let mut buf = [0u8; 4];
            for b in c.encode_utf8(&mut buf).as_bytes() {
                out.push_str(&format!("%{:02X}", b));
            }
        } else {
            out.push(c);
        }
    }
    out
}

pub fn resolve(base: &Url, reference: &str) -> Option<Url> {
    // If the reference has a scheme, it is parsed on its own.
    let r = parse(reference);
    if let Some(u) = r {
        return Some(u);
    }
    let mut u = base.clone();
    if reference.is_empty() {
        u.fragment = None;
        return Some(u);
    }
    let chars: Vec<char> = reference.chars().collect();
    if chars[0] == '#' {
        u.fragment = Some(encode_component(&reference[1..], &[], "\"<>`"));
        return Some(u);
    }
    if chars[0] == '?' {
        u.query = Some(encode_component(&reference[1..], &[], "\"#<>`"));
        return Some(u);
    }
    if chars.len() >= 2 && chars[0] == '/' && chars[1] == '/' {
        // Scheme relative: keep the base scheme, replace the authority.
        let rest: String = chars[2..].iter().collect();
        let mut abs = format!("{}://{}", base.scheme, rest);
        let mut parsed = parse(&abs)?;
        // merge query/fragment handling already done by parse
        let _ = &mut parsed;
        return Some(parsed);
    }
    // Path relative
    let (path, query, fragment) = split_path_query_fragment(reference);
    let base_dir = match base.path.rfind('/') {
        Some(p) => base.path[..p].to_string(),
        None => String::new(),
    };
    let combined = if path.starts_with('/') {
        path
    } else {
        format!("{}/{}", base_dir, path)
    };
    u.path = normalize_path(&combined, is_special(&base.scheme));
    u.path = encode_component(&u.path, &[], "\"<>`{}");
    u.query = query.map(|q| encode_component(&q, &[], "\"#<>`"));
    u.fragment = fragment.map(|f| encode_component(&f, &[], "\"<>`"));
    Some(u)
}
