                out.push(' ');
                out.push_str(&ns_prefix(&k.ns, &k.local));
                out.push_str("=\"");
                escape_attr(v, out);
                out.push('"');
            }
            out.push('>');
            let raw = is_raw(tree, node);
            // Decide the depth for children.
            let child_depth = depth + 1;
            let prev_block_ancestor = {
                let mut any = false;
                let mut n = tree.parent(node);
                while let Some(p) = n {
                    if is_block_elem(tree, p) && has_prev_block_sibling(tree, p) {
                        any = true;
                        break;
                    }
                    n = tree.parent(p);
                }
                any
            };
            for (i, &c) in tree.children(node).to_vec().iter().enumerate() {
                let cblock = is_block_elem(tree, c);
                let prev = if i == 0 { None } else { Some(tree.children(node)[i - 1]) };
                let prev_block = match prev {
                    Some(p) => is_block_elem(tree, p),
                    None => false,
                };
                let mut need = cblock || prev_block;
                if !need && !cblock {
                    // first child / after a comment, and an ancestor had a
                    // preceding block sibling
                    if prev.is_none() || is_comment(tree, prev.unwrap()) {
                        if prev_block_ancestor {
                            need = !matches!(tree.data(c), NodeData::Comment(_));
                        }
                    }
                }
                if need {
                    out.push('\n');
                    indent(out, child_depth);
                }
                if raw {
                    if let NodeData::Text(t) = tree.data(c) {
                        out.push_str(t);
                        continue;
                    }
                }
                pretty_node(tree, c, child_depth, out, prev_block_ancestor);
            }
            if block {
                out.push('\n');
                indent(out, depth);
            }
            if !is_void(tree, node) {
                out.push_str("</");
                out.push_str(&ns_prefix(&e.name.ns, &e.name.local));
                out.push('>');
            }
        }
    }
}

fn is_comment(tree: &Tree, node: usize) -> bool {
    matches!(tree.data(node), NodeData::Comment(_))
}
